def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 > v2:
        value = 2019
        comparison = "2019 greater than 2018"
    elif v2 > v1:
        value = 2018
        comparison = "2018 greater than 2019"
    else:
        value = None
        comparison = "Equal"

    return {
        "value": value,
        "trace": {
            "v1": v1,
            "v2": v2,
            "comparison": comparison,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
